create function public.admin_dashboard(p_season uuid default null) returns jsonb language plpgsql stable security definer set search_path=public as $$declare output jsonb;begin if admin_role() not in ('admin','super_admin') or admin_role() is null then raise exception 'Unauthorized';end if;
with r as(select * from registrations where p_season is null or season_id=p_season)
select jsonb_build_object('total_registrasi',count(*),'pending',count(*) filter(where payment_status='pending'),'paid',count(*) filter(where payment_status='paid'),'fotogenik',count(*) filter(where competition_type='photogenic'),'mewarnai',count(*) filter(where competition_type='coloring'),'karya_pending',(select count(*) from submissions s join r on r.id=s.registration_id where s.status='pending_review'),'karya_approved',(select count(*) from submissions s join r on r.id=s.registration_id where s.status='approved'),'klaim',(select count(*) from claim_invoices c join r on r.id=c.registration_id),'pengiriman',(select count(*) from shipments s join r on r.id=s.registration_id),'per_kategori',(select jsonb_object_agg(category,n) from(select category,count(*) n from r group by category) a),'per_provinsi',(select jsonb_object_agg(province_name,n) from(select p.province_name,count(*) n from r join participants p on p.id=r.participant_id group by p.province_name) a),'sumber_registrasi',(select jsonb_object_agg(registration_source,n) from(select registration_source,count(*) n from r group by registration_source) a)) into output from r;return output;end$$;
revoke all on function admin_dashboard(uuid) from public,anon;grant execute on function admin_dashboard(uuid) to authenticated;
